demo3_in = [[9,9,9],[9,5,9],[9,5,9],[9,9,9],[9,9,9]]
demo3_out = [[9,9,9],[9,5,9],[9,5,9],[9,9,9],[9,9,9],[9,9,9]]

print("Demo 3:")
