for i, row in enumerate(demo3_out): print(f"Out {i}: {row}")

bg = 2
cross = 6
w = 12

# Approach: Equal distribution across pattern elements  
element_order = ['A', 'P', 'F', 'F', 'P', 'P', 'F', 'F', 'P', 'A']

final = []
pos_idx = 0

for ro in range(20):
    stype = element_order[pos_idx]

    if stype == 'A':
        final.append([bg]*w)
    elif stype == 'P':
        final.append([bg] + [cross]*(w-2) + [bg])
    else:
        final.append([cross]*w)

    pos_idx += 1

print("Direct sequence (no scaling):")
for i, row in enumerate(final):
    typ = "?"
    if all(c == bg for c in row):
        typ = "A"
    elif all(c == cross for c in row):
        typ = "F"
    elif row[0] == bg and row[-1] == bg:
        typ = "P"
    print(f"{i}: {typ}")

bg = 2
cross = 6
w = 12

element_order = ['A', 'P', 'F', 'F', 'P', 'P', 'F', 'F', 'P', 'A']

final = []
pos_idx = 0

for ro in range(20):
    stype = element_order[pos_idx % len(element_order)]  # Wrap around

    if stype == 'A':
        final.append([bg]*w)
    elif stype == 'P':
        final.append([bg] + [cross]*(w-2) + [bg])
    else:
        final.append([cross]*w)

    pos_idx += 1

print("Repeating sequence:")
for i, row in enumerate(final):
    typ = "?"
    if all(c == bg for c in row):
        typ = "A"
    elif all(c == cross for c in row):
        typ = "F"
    elif row[0] == bg and row[-1] == bg:
        typ = "P"
    print(f"{i}: {typ}")

# Simplest possible: Alternating P and F starting with PARTIAL
bg = 2
cross = 6
w = 12
h_out = 20

final = []

for ro in range(h_out):
    if ro == 0 or ro == h_out - 1:
        final.append([bg]*w)  # Edge rows
    elif ro % 2 == 0:
        final.append([cross]*w)  # Even rows: FULL
    else:
        final.append([bg] + [cross]*(w-2) + [bg])  # Odd rows: PARTIAL

print("Simple alternating:")
for i, row in enumerate(final):
    typ = "?"
    if all(c == bg for c in row):
        typ = "A"
    elif all(c == cross for c in row):
        typ = "F"
    elif row[0] == bg and row[-1] == bg:
        typ = "P"
    print(f"{i}: {typ}")

